<script setup lang="ts">
const {data}=await useFetch<any>('/api/settings'); const form=reactive({displayName:'',dailyMinutes:30,dailyNewCharacters:5,maxReviews:20,showPinyin:true,theme:'system'}); watch(data,v=>{if(v)Object.assign(form,{displayName:v.display_name,dailyMinutes:v.daily_minutes,dailyNewCharacters:v.daily_new_characters,maxReviews:v.max_reviews,showPinyin:v.show_pinyin,theme:v.theme})},{immediate:true}); const saved=ref(false); const save=async()=>{await $fetch('/api/settings',{method:'POST',body:form});saved.value=true;setTimeout(()=>saved.value=false,2000)}; const exportBackup=async()=>{const b=await $fetch('/api/backup');const blob=new Blob([JSON.stringify(b,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`hanzipath-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href)}; const importBackup=async(e:any)=>{const file=e.target.files?.[0];if(!file)return;try{await $fetch('/api/backup',{method:'POST',body:JSON.parse(await file.text())});alert('Backup importado com sucesso.')}catch{alert('Backup inválido ou incompatível.')}}
</script>
<template><section><div class="page-title"><span class="eyebrow">PREFERÊNCIAS</span><h1>Configurações</h1><p class="muted">As configurações e o progresso são persistidos no Neon.</p></div><div class="card" style="max-width:700px"><label class="list-row"><span class="row-main"><b>Nome de exibição</b></span><input v-model="form.displayName" class="input" style="max-width:220px"></label><label class="list-row"><span class="row-main"><b>Meta diária (minutos)</b></span><input v-model.number="form.dailyMinutes" class="input" style="max-width:100px" type="number"></label><label class="list-row"><span class="row-main"><b>Novos caracteres por dia</b></span><input v-model.number="form.dailyNewCharacters" class="input" style="max-width:100px" type="number"></label><label class="list-row"><span class="row-main"><b>Máximo de revisões</b></span><input v-model.number="form.maxReviews" class="input" style="max-width:100px" type="number"></label><label class="list-row"><span class="row-main"><b>Mostrar Pinyin automaticamente</b></span><input v-model="form.showPinyin" type="checkbox"></label><button class="button primary" style="margin-top:20px" @click="save">{{saved?'Salvo ✓':'Salvar preferências'}}</button><hr style="border:0;border-top:1px solid var(--line);margin:28px 0"><h3>Backup dos seus dados</h3><p class="muted">Inclui progresso, configurações, cartões, revisões e aulas concluídas.</p><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="button" @click="exportBackup">Exportar JSON</button><label class="button" style="cursor:pointer">Importar JSON<input type="file" accept="application/json" hidden @change="importBackup"></label></div></div></section></template>
